import {defineRouteMiddleware, type StarlightRouteData} from '@astrojs/starlight/route-data';

type SidebarEntry = StarlightRouteData['sidebar'][number];

const capitalize = (label: string) => label.charAt(0).toUpperCase() + label.slice(1);

/** Autogenerated groups are labelled with their directory name: "configuration" → "Configuration". */
function relabel(entries: SidebarEntry[]): SidebarEntry[] {
    return entries.map((entry) => entry.type === 'group'
        ? {...entry, label: capitalize(entry.label), entries: relabel(entry.entries)}
        : entry);
}

export const onRequest = defineRouteMiddleware(async (context, next) => {
    await next();
    const route = context.locals.starlightRoute;
    route.sidebar = relabel(route.sidebar);
});
